package com.fluxisai.task;
import java.net.URI; import java.util.UUID; import com.fluxisai.common.web.PageResponse; import jakarta.validation.Valid; import org.springframework.data.domain.*; import org.springframework.data.web.PageableDefault; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.servlet.support.ServletUriComponentsBuilder;
@RestController @RequestMapping("/api/tasks") public class TaskController {private final TaskService service;public TaskController(TaskService s){service=s;} @PostMapping public ResponseEntity<TaskResponse> create(@Valid @RequestBody TaskRequest r){var c=service.create(r);URI location=ServletUriComponentsBuilder.fromCurrentRequest().path("/{id}").buildAndExpand(c.id()).toUri();return ResponseEntity.created(location).body(c);}@GetMapping public PageResponse<TaskResponse> list(@PageableDefault(size=50,sort="dueDate",direction=Sort.Direction.ASC)Pageable p){return service.list(p);}@GetMapping("/{id}") public TaskResponse get(@PathVariable UUID id){return service.get(id);}@PutMapping("/{id}") public TaskResponse update(@PathVariable UUID id,@Valid @RequestBody TaskRequest r){return service.update(id,r);}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable UUID id){service.delete(id);}}
